  function brandLogo(name, cls, fbBg) {
    const n = String(name || '');
    const hit = BRAND_LOGOS.find((b) => b.re.test(n));
    const c = cls || 'sm';
    if (hit) {
      const inner = hit.d
        ? `<svg viewBox="0 0 24 24" width="62%" height="62%" style="display:block"><path fill="${hit.fg}" d="${hit.d}"/></svg>`
        : `<span style="color:${hit.fg};font-weight:800;font-size:${(hit.t||'').length>1?'11px':'16px'};line-height:1;letter-spacing:-.02em">${esc(hit.t)}</span>`;
      return `<div class="avatar ${c}" style="background:${hit.bg};display:flex;align-items:center;justify-content:center;overflow:hidden">${inner}</div>`;
    }
    return `<div class="avatar ${c}" style="background:${fbBg || '#6b7280'};font-size:14px">${esc(initials(n))}</div>`;
  }

