  /* ============================================================
   *  云端同步（GitHub Gist）—— 可选，默认关闭
   *  数据经 AES-GCM 端到端加密后存入你的「私密 Gist」；
   *  两端填相同 GitHub Token + 同步密码 即可共享（Gist ID 首次同步自动生成）。
   * ============================================================ */
  const SYNC = {
    token: (function () { try { return localStorage.getItem('ghToken') || ''; } catch (e) { return ''; } })(),
    gistId: (function () { try { return localStorage.getItem('ghGistId') || ''; } catch (e) { return ''; } })(),
    pass: (function () { try { return localStorage.getItem('ghPass') || ''; } catch (e) { return ''; } })(),
    on: (function () { try { return localStorage.getItem('ghOn') === '1'; } catch (e) { return false; } })(),
    ready: false, pushTimer: null, _status: 'off',
  };
  const GH_API = 'https://api.github.com';
  const SYNC_FILE = 'wool-sync.json';

  function cbStatus(kind, msg) {
    SYNC._status = kind; SYNC._msg = msg || '';
    const el = document.getElementById('syncStat');
    if (!el) return;
    const map = {
      ok: ['已同步', 'var(--t)'], syncing: ['同步中…', 'var(--p)'],
      err: ['同步异常', 'var(--err)'], off: ['未开启', 'var(--txt2)'],
    };
    const m = map[kind] || map.off;
    el.textContent = m[0] + (msg && kind === 'err' ? '：' + msg : '');
    el.style.color = m[1];
  }
  async function cbDeriveKey(pass, salt) {
    const enc = new TextEncoder();
    const base = await crypto.subtle.importKey('raw', enc.encode(pass), 'PBKDF2', false, ['deriveKey']);
    return crypto.subtle.deriveKey({ name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' }, base, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
  }
  async function cbEncrypt(obj, pass) {
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const key = await cbDeriveKey(pass, salt);
    const data = new TextEncoder().encode(JSON.stringify(obj));
    const ct = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, data);
    const buf = new Uint8Array(16 + 12 + ct.byteLength);
    buf.set(salt, 0); buf.set(iv, 16); buf.set(new Uint8Array(ct), 28);
    let bin = '';
    for (let i = 0; i < buf.length; i++) bin += String.fromCharCode(buf[i]);
    return btoa(bin);
  }
  async function cbDecrypt(b64s, pass) {
    const bin = atob(b64s);
    const buf = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
    const salt = buf.slice(0, 16), iv = buf.slice(16, 28), ct = buf.slice(28);
    const key = await cbDeriveKey(pass, salt);
    const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ct);
    return JSON.parse(new TextDecoder().decode(pt));
  }
  async function ghReq(path, opts) {
    const headers = {
      'Authorization': 'Bearer ' + SYNC.token,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json',
      'X-GitHub-Api-Version': '2022-11-28',
    };
    const r = await fetch(GH_API + path, Object.assign({ headers }, opts || {}));
    if (!r.ok) {
      let detail = '';
      try { const j = await r.json(); detail = j.message || ''; } catch (e) {}
      throw new Error('GitHub 返回 ' + r.status + (detail ? '：' + detail : ''));
    }
    if (r.status === 204) return null;
    return r.json();
  }
  async function cbInit() {
    if (!SYNC.token) throw new Error('未填写 GitHub Token');
    SYNC.ready = true;
  }
  async function cbPush(st) {
    if (!SYNC.on || !SYNC.token) return;
    if (!SYNC.ready) { try { await cbInit(); } catch (e) { cbStatus('err', e.message); return; } }
    try {
      cbStatus('syncing');
      // 密码必填：弱默认密码等于任何拿到 secret Gist URL 的人都能解密
      const blob = await cbEncrypt(st, SYNC.pass || (() => { throw new Error('请先设置同步密码'); })());
      if (!SYNC.gistId) {
        const created = await ghReq('/gists', {
          method: 'POST',
          body: JSON.stringify({ public: false, description: '别忘了羊毛 · 同步备份', files: { [SYNC_FILE]: { content: blob } } }),
        });
        SYNC.gistId = created.id;
        try { localStorage.setItem('ghGistId', SYNC.gistId); } catch (e) {}
      } else {
        await ghReq('/gists/' + SYNC.gistId, {
          method: 'PATCH',
          body: JSON.stringify({ files: { [SYNC_FILE]: { content: blob } } }),
        });
      }
      cbStatus('ok');
    } catch (e) { cbStatus('err', e.message); }
  }
  async function cbPull() {
    if (!SYNC.on || !SYNC.token) return null;
    if (!SYNC.ready) { try { await cbInit(); } catch (e) { cbStatus('err', e.message); return null; } }
    if (!SYNC.gistId) return null;
    try {
      const g = await ghReq('/gists/' + SYNC.gistId);
      const f = g.files && g.files[SYNC_FILE];
      if (!f || !f.content) return null;
      const st = await cbDecrypt(f.content, SYNC.pass || (() => { throw new Error('请先设置同步密码'); })());
      cbStatus('ok');
      return st;
    } catch (e) { cbStatus('err', e.message); return null; }
  }
  function scheduleSyncPush() {
    if (!SYNC.on || !SYNC.token) return;
    clearTimeout(SYNC.pushTimer);
    SYNC.pushTimer = setTimeout(() => { cbPush(state); }, 800);
  }
  async function initCloudSync() {
    if (!SYNC.on || !SYNC.token) { cbStatus('off'); return; }
    const remote = await cbPull();
    if (remote && remote.creditCards) {
      state = remote;
      if (state.benefitTags && Array.isArray(state.benefitTags) && state.benefitTags.length) BENEFIT_TAGS = state.benefitTags;
      persist();
      // 云端拉回的 pushCfg 覆盖本地缓存，保持多端一致
      try {
        if (state.pushCfg) localStorage.setItem('btpush_cfg', JSON.stringify(state.pushCfg));
      } catch (e) {}
      if (typeof rerender === 'function') rerender();
      toast('已从云端同步');
    }
  }

  let state = (function loadState() {
    try { const s = JSON.parse(localStorage.getItem(STORE_KEY)); if (s && s.creditCards) return s; } catch (e) {}
    const s = seedData(); try { localStorage.setItem(STORE_KEY, JSON.stringify(s)); } catch (e) {} return s;
  })();
  // Sync editable benefit-tag definitions from persisted state (if any).
  if (state.benefitTags && Array.isArray(state.benefitTags) && state.benefitTags.length) {
    BENEFIT_TAGS = state.benefitTags;
  }
  // One-time migration: re-classify benefits that are untagged / invalid / "其他"
  // using the improved name→tag inference, so legacy & hand-added benefits land in
  // the right bucket (旅行不便险→保险, 9元观影→电影, 星巴克→咖啡, 酒店升级→酒店 …).
  // Also re-disambiguates lounge subtypes (贵宾楼 vs 贵宾厅 vs 高铁 vs 通道) by name.
  (function recatMigration() {
    if (state._recatV === APP_VERSION) return;
    const valid = new Set(BENEFIT_TAGS.map((t) => t.v));
    const loungeTags = ['airport_lounge', 'airport_vip', 'train_lounge', 'airport_fast'];
    let changed = false;
    state.creditCards.forEach((c) => c.benefits.forEach((b) => {
      const tag = b.tag;
      const reclassifiable = !tag || !valid.has(tag) || tag === 'other' || loungeTags.includes(tag);
      if (reclassifiable) {
        const nv = resolveBenefitTag(b);
        if (nv !== tag) { b.tag = nv; changed = true; }
      }
    }));
    state._recatV = APP_VERSION;
    if (changed) persist();
  })();
  // Normalize: custom ordering of the home hero quick-view benefit tiles.
  if (!Array.isArray(state.homeTileOrder)) state.homeTileOrder = [];
  // Migration: independent voucher brands (商家可先建、后加券)。
  if (!Array.isArray(state.voucherBrands)) state.voucherBrands = [];
  function persist(s) { try { localStorage.setItem(STORE_KEY, JSON.stringify(s || state)); } catch (e) {} scheduleSyncPush(); }

  /* ============================================================
   *  DOM refs
   * ============================================================ */
  const $page = document.getElementById('page');
  const $modal = document.getElementById('modalHost');
  const $toast = document.getElementById('toastHost');

  /* ============================================================
   *  Toast & Sheet
   * ============================================================ */
  let toastTimer;
  function toast(msg) {
    $toast.innerHTML = `<div class="toast">${esc(msg)}</div>`;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => ($toast.innerHTML = ''), 1900);
  }
  function openSheet(title, body, onMount) {
    $modal.innerHTML = `<div class="modal-mask" data-close="1"><div class="sheet" onclick="event.stopPropagation()">
      <div class="grabber"></div>
      <div class="sheet-head"><div class="t">${esc(title)}</div>
      <button class="topbar-act" data-close="1"><span class="ms">✕</span></button></div>
      <div class="sheet-body">${body}</div>
    </div></div>`;
    $modal.querySelectorAll('[data-close]').forEach((b) => b.addEventListener('click', closeSheet));
    if (onMount) onMount($modal.querySelector('.sheet-body'));
  }
  function closeSheet() { $modal.innerHTML = ''; rerender(); }

  /* ============================================================
   *  Sheet: reorder the home hero quick-view benefit tiles
   *  Supports drag-and-drop as well as ▲/▼ buttons; persists the
   *  resulting key order to state.homeTileOrder.
   * ============================================================ */
  function openHomeOrderSheet() {
    const cur = mergedBenefits();                 // currently visible kinds
    const meta = new Map(cur.map((g) => [g.gk, g]));
    let tmp = orderByTileOrder(cur).map((g) => g.gk);
    const body = `
      <p class="muted" style="font-size:12px;margin:0 0 12px;line-height:1.5">
        拖动卡片或点 ▲▼ 调整首页「快捷权益」的排列，最上面的会排在最前面。
      </p>
      <div id="orderList" class="order-list"></div>
      <div class="flex gap-sm mt-lg">
        <button class="btn btn-ghost flex main justify-center" id="orderReset">恢复默认</button>
        <button class="btn btn-primary flex main justify-center" id="orderDone">完成</button>
      </div>`;
    openSheet('编排权益顺序', body, ($b) => {
      const listEl = $b.querySelector('#orderList');
      function render() {
        listEl.innerHTML = tmp.map((k, i) => {
          const g = meta.get(k);
          return `<div class="order-item" draggable="true" data-k="${k}">
            <span class="oi-drag"><span class="ms">⠿</span></span>
            <span class="oi-ic">${g.ic}</span>
            <span class="oi-lbl">${esc(g.k)}</span>
            <span class="oi-act">
              <button class="oi-btn" data-move="up" ${i === 0 ? 'disabled' : ''} aria-label="上移"><span class="ms">↑</span></button>
              <button class="oi-btn" data-move="down" ${i === tmp.length - 1 ? 'disabled' : ''} aria-label="下移"><span class="ms">↓</span></button>
            </span>
          </div>`;
        }).join('');
        wire();
      }
      function wire() {
        listEl.querySelectorAll('.order-item').forEach((el) => {
          const k = el.dataset.k;
          el.querySelectorAll('[data-move]').forEach((btn) => {
            btn.addEventListener('click', () => {
              const i = tmp.indexOf(k);
              const j = i + (btn.dataset.move === 'up' ? -1 : 1);
              if (j < 0 || j >= tmp.length) return;
              [tmp[i], tmp[j]] = [tmp[j], tmp[i]];
              render();
            });
          });
          el.addEventListener('dragstart', (e) => { el.classList.add('dragging'); e.dataTransfer.setData('text/plain', k); });
          el.addEventListener('dragend', () => el.classList.remove('dragging'));
          el.addEventListener('dragover', (e) => { e.preventDefault(); el.classList.add('drag-over'); });
          el.addEventListener('dragleave', () => el.classList.remove('drag-over'));
          el.addEventListener('drop', (e) => {
            e.preventDefault();
            el.classList.remove('drag-over');
            const from = tmp.indexOf(e.dataTransfer.getData('text/plain'));
            const to = tmp.indexOf(k);
            if (from < 0 || to < 0 || from === to) return;
            tmp.splice(to, 0, tmp.splice(from, 1)[0]);
            render();
          });
        });
      }
      render();
      $b.querySelector('#orderDone').addEventListener('click', () => {
        state.homeTileOrder = tmp.slice();
        persist();
        closeSheet();
        toast('已保存权益顺序');
      });
      $b.querySelector('#orderReset').addEventListener('click', () => {
        state.homeTileOrder = [];
        tmp = cur.map((g) => g.gk);
        persist();
        render();
        toast('已恢复默认顺序');
      });
    });
  }

  /* Re-render the current route without touching the history stack.
     Guarantees that mutations made inside a sheet (e.g. adding a credit-card
     benefit) are reflected on the page underneath as soon as the sheet closes. */
  function rerender() {
    const r = currentRoute;
    let html = '';
    switch (r.name) {
      case 'home': html = renderHome(); break;
      case 'assets': html = renderAssets(r.param || 'all'); break;
      case 'creditcards': html = renderCreditCards(); break;
      case 'creditDetail': html = renderCreditDetail(r.param); break;
      case 'membershipDetail': html = renderMembershipDetail(r.param); break;
      case 'vouchers': html = renderVouchers(); break;
      case 'voucherHistory': html = renderVoucherHistory(); break;
      case 'voucherBrand': html = renderVoucherBrand(r.param); break;
      case 'voucherDetail': html = renderVoucherDetail(r.param); break;
      case 'benefitDetail': html = renderBenefitDetail(r.param); break;
      case 'knowledgeDetail': html = renderKnowledgeDetail(r.param); break;
      case 'knowledge':
      case 'knowledgeSummary': html = renderKnowledgeSummary(); break;
      case 'knowledgeSubs': html = renderKnowledgeSubs(); break;
      case 'knowledgePurchases': html = renderKnowledgePurchases(); break;
      case 'knowledgeExpiry': html = renderKnowledgeExpiry(); break;
      case 'countdown': html = renderCountdown(); break;
      case 'mergeDetail': html = renderMergeDetail(r.param); break;
      case 'stats': html = renderStats(); break;
      case 'notify': html = renderNotify(); break;
      case 'settings': html = renderSettings(); break;
      case 'tagManage': html = renderTagManage(); break;
      case 'tagManageCards': html = renderTagManageCards(); break;
      default: html = renderHome();
    }
    // Keep the bottom tab highlight in sync with whatever route we just rendered,
    // so closing any sheet / in-page mutation always lands on the correct tab.
    const routeTab = {
      home: 'home', countdown: 'home', mergeDetail: 'home',
      assets: 'assets', membershipDetail: 'assets',
      creditcards: 'credit', creditDetail: 'credit',
      vouchers: 'voucher', voucherBrand: 'voucher', voucherHistory: 'voucher',
      voucherDetail: 'voucher',
      benefitDetail: 'credit',
      knowledge: 'knowledge', knowledgeSummary: 'knowledge', knowledgeDetail: 'knowledge',
      knowledgeSubs: 'knowledge', knowledgePurchases: 'knowledge',
      knowledgeExpiry: 'knowledge',
      stats: 'profile', settings: 'profile',
      notify: 'notify',
    }[r.name] || 'home';
    setActiveTab(routeTab);
    $page.innerHTML = html;
    // Show floating back button on non-tab (deep) pages
    const floatBack = document.getElementById('floatBack');
    const tabPages = ['home', 'assets', 'creditcards', 'knowledge', 'settings'];
    if (floatBack) floatBack.style.display = tabPages.includes(r.name) ? 'none' : 'flex';
  }

  /* ============================================================
   *  Router
   * ============================================================ */
  let historyStack = [];
  let currentTop = 'home';
  let currentRoute = { name: 'home', param: null };
  let mergeKind = null;

  function setActiveTab(name) {
    document.querySelectorAll('#tabbar .nav-item').forEach((t) => {
      t.classList.toggle('active', t.dataset.tab === name);
    });
  }

  function navigate(name, param) {
    currentRoute = { name, param: param || null };
    const routed = {
      home: 'home', vouchers: 'voucher', creditcards: 'credit', assets: 'assets', stats: 'stats', settings: 'profile',
    }[name];
    if (routed) { currentTop = routed; historyStack = [name]; }
    else {
      // Avoid pushing a duplicate of the current top — re-navigating the same
      // deep page (e.g. after 核销/撤销/编辑) would otherwise stack dupes and
      // make the floating back button appear to "do nothing".
      const last = historyStack[historyStack.length - 1];
      const same = (typeof last === 'string')
        ? (last === name)
        : (last.name === name && last.param === (param || null));
      if (!same) historyStack.push({ name: name, param: param || null });
    }

    let html = '';
    switch (name) {
      case 'home': html = renderHome(); setActiveTab('home'); break;
      case 'assets': html = renderAssets(param || 'all'); setActiveTab('assets'); break;
      case 'creditDetail': html = renderCreditDetail(param); setActiveTab('credit'); break;
      case 'membershipDetail': html = renderMembershipDetail(param); setActiveTab('assets'); break;
      case 'creditcards': html = renderCreditCards(); setActiveTab('credit'); break;
      case 'vouchers': html = renderVouchers(); setActiveTab('voucher'); break;
      case 'voucherBrand': html = renderVoucherBrand(param); setActiveTab('voucher'); break;
      case 'voucherHistory': html = renderVoucherHistory(); setActiveTab('voucher'); break;
      case 'voucherDetail': html = renderVoucherDetail(param); setActiveTab('voucher'); break;
      case 'benefitDetail': html = renderBenefitDetail(param); setActiveTab('credit'); break;
      case 'knowledgeDetail': html = renderKnowledgeDetail(param); setActiveTab('knowledge'); break;
      case 'knowledge':
      case 'knowledgeSummary': html = renderKnowledgeSummary(); setActiveTab('knowledge'); break;
      case 'knowledgeSubs': html = renderKnowledgeSubs(); setActiveTab('knowledge'); break;
      case 'knowledgePurchases': html = renderKnowledgePurchases(); setActiveTab('knowledge'); break;
      case 'knowledgeExpiry': html = renderKnowledgeExpiry(); setActiveTab('knowledge'); break;
      case 'countdown': html = renderCountdown(); setActiveTab('home'); break;
      case 'mergeDetail': html = renderMergeDetail(param); setActiveTab('home'); break;
      case 'stats': html = renderStats(); setActiveTab('profile'); break;
      case 'knowledgeSummary': html = renderKnowledgeSummary(); setActiveTab('profile'); break;
      case 'notify': html = renderNotify(); setActiveTab('notify'); break;
      case 'settings': html = renderSettings(); setActiveTab('profile'); break;
      case 'tagManage': html = renderTagManage(); setActiveTab('profile'); break;
      case 'tagManageCards': html = renderTagManageCards(); setActiveTab('profile'); break;
      default: html = renderHome(); setActiveTab('home');
    }
    $page.innerHTML = html;
    $page.scrollTop = 0;
    // Show floating back button on non-tab (deep) pages
    const floatBack = document.getElementById('floatBack');
    const tabPages = ['home', 'vouchers', 'assets', 'creditcards', 'knowledge', 'settings'];
    if (floatBack) floatBack.style.display = tabPages.includes(name) ? 'none' : 'flex';
  }

  function back() {
    if (historyStack.length > 1) {
      historyStack.pop();
      const prev = historyStack[historyStack.length - 1];
      navigate(typeof prev === 'string' ? prev : prev.name, typeof prev === 'string' ? null : prev.param);
    } else { navigate(historyStack[0] || 'home'); }
  }

