  /* ============================================================
   *  Page: Notify Center (Screen _7)
   * ============================================================ */
  function notifyItems() {
    const tl = [];
    expiringItems().forEach((it) => {
      if (!it.expiry) return;
      const d = daysLeft(it.expiry);
      if (d > 30) return;
      const u = urgency(it.expiry);
      tl.push({ level: u.level === 'urgent' ? 'urgent' : u.level === 'soon' ? 'warn' : 'info', title: `${it.name} ${it.kind === 'credit' ? '权益' : (it.kind === 'voucher' ? '卡/票' : '')}即将到期`, desc: `${it.kind === 'credit' ? '信用卡权益' : it.kind === 'voucher' ? '卡/票' : cat(it.cat).l} · 剩余 ${d} 天`, date: d <= 0 ? '已过期' : `${d} 天后` });
    });
    state.creditCards.forEach((c) => { if ((c.fee || 0) > 0) tl.push({ level: 'info', title: `${c.bank}${c.name} 年费提醒`, desc: `年费 ${money2(c.fee)} · 续持卡前可评估权益是否回本`, date: '年费' }); });
    const order = { urgent: 0, warn: 1, info: 2, ok: 3 };
    tl.sort((a, b) => (order[a.level] - order[b.level]) || 0);
    return tl;
  }

